#include "mspa/c_api.h"
#include "mspa/runtime/runtime.hpp"
#include "mspa/base/version.hpp"
#include <cstdlib>
#include <cstring>
#include <memory>
#include <new>
#include <string>
#include <vector>
using namespace mspa;
struct mspa_runtime { std::unique_ptr<Runtime> impl; };
namespace {thread_local std::string err; mspa_status status(ErrorCode c){switch(c){case ErrorCode::None:return MSPA_OK;case ErrorCode::InvalidArgument:return MSPA_INVALID_ARGUMENT;case ErrorCode::UnknownAgent:return MSPA_UNKNOWN_AGENT;case ErrorCode::DuplicateAgent:return MSPA_DUPLICATE_AGENT;case ErrorCode::InvalidState:return MSPA_INVALID_STATE;case ErrorCode::InvalidPack:return MSPA_INVALID_PACK;case ErrorCode::QuotaExceeded:return MSPA_QUOTA_EXCEEDED;case ErrorCode::VersionMismatch:return MSPA_VERSION_MISMATCH;case ErrorCode::NamespaceConflict:return MSPA_NAMESPACE_CONFLICT;case ErrorCode::TimeRegression:return MSPA_TIME_REGRESSION;case ErrorCode::BatchConflict:return MSPA_BATCH_CONFLICT;case ErrorCode::OutOfMemory:return MSPA_OUT_OF_MEMORY;case ErrorCode::UnsupportedOperation:return MSPA_UNSUPPORTED_OPERATION;case ErrorCode::SerializationError:return MSPA_SERIALIZATION_ERROR;default:return MSPA_INTERNAL_ERROR;}}template<class T>mspa_status take(const Result<T>&r){if(r)return MSPA_OK;err=r.error_if()?r.error_if()->details:"unknown MSPA error";return r.error_if()?status(r.error_if()->code):MSPA_INTERNAL_ERROR;}AgentId aid(mspa_agent_id a){return {WorldId(a.world),a.local_id};}mspa_agent_id caid(AgentId a){return {a.world.value(),a.local_id};}}
namespace {
ActionOption convert_option(const mspa_action_option& src, AgentId actor) {
    ActionOption o{}; o.type=ActionTypeId(src.type_id);o.instance=ActionInstanceId(src.instance_id);o.continuity=ActionContinuityKey(src.continuity_key);o.actor=actor;o.cost=src.cost;o.risk=src.risk;o.progress=src.progress;o.novelty=src.novelty;o.social_exposure=src.social_exposure;o.interruption_cost=src.interruption_cost;o.context_stability=src.context_stability;
    if(src.context_tags) for(size_t i=0;i<src.context_tag_count;++i) if(src.context_tags[i]) o.context_tags.emplace_back(src.context_tags[i]);
    if(src.expected_effects) for(size_t i=0;i<src.expected_effect_count;++i){const auto&e=src.expected_effects[i];ExpectedEffect x{};x.channel=static_cast<EffectChannel>(e.channel);x.concept_id=ConceptId(e.concept_id);x.target=aid(e.target);x.magnitude=e.magnitude;if(e.outcome_tag)x.outcome_tag=e.outcome_tag;o.expected_effects.push_back(std::move(x));}
    if(src.signals) for(size_t i=0;i<src.signal_count;++i) if(src.signals[i].name) o.signals[src.signals[i].name]=src.signals[i].value;
    return o;
}
mspa_status fill_decision(const Result<Decision>& q,mspa_decision_result*out){auto s=take(q);if(s!=MSPA_OK)return s;out->has_selection=q.value_if()->has_selection;out->selected_action=q.value_if()->selected_action.value();out->selected_target=caid(q.value_if()->selected_target);out->confidence=q.value_if()->confidence;return MSPA_OK;}
}
extern "C" {
uint32_t mspa_version_major(void){return runtime_version_major;}uint32_t mspa_version_minor(void){return runtime_version_minor;}uint32_t mspa_version_patch(void){return runtime_version_patch;}
mspa_status mspa_runtime_create(const mspa_runtime_config*c,mspa_runtime**out){try{if(!c||!out)return MSPA_INVALID_ARGUMENT;RuntimeConfig x{};x.runtime_id=RuntimeId(c->runtime_id);x.world_id=WorldId(c->world_id);x.time_domain={TimeDomainId(c->time_domain_id),{c->ticks_per_second_num,c->ticks_per_second_den}};x.seed_root=c->seed_root;x.diagnostics_enabled=c->diagnostics_enabled!=0;auto r=Runtime::create(x);auto s=take(r);if(s!=MSPA_OK)return s;auto h=new mspa_runtime;h->impl=std::move(*r.value_if());*out=h;err.clear();return MSPA_OK;}catch(const std::bad_alloc&){err="out of memory";return MSPA_OUT_OF_MEMORY;}catch(...){err="unexpected C ABI exception";return MSPA_INTERNAL_ERROR;}}
void mspa_runtime_destroy(mspa_runtime*r){delete r;}
mspa_status mspa_agent_create(mspa_runtime*r,mspa_agent_id a,uint64_t t){if(!r)return MSPA_INVALID_ARGUMENT;auto q=r->impl->create_agent(aid(a),AgentInit{},PsychTime(t));return take(q);}mspa_status mspa_agent_remove(mspa_runtime*r,mspa_agent_id a,uint64_t t){if(!r)return MSPA_INVALID_ARGUMENT;auto q=r->impl->remove_agent(aid(a),PsychTime(t));return take(q);}int mspa_agent_has(const mspa_runtime*r,mspa_agent_id a){return r&&r->impl->has_agent(aid(a));}
mspa_status mspa_observe(mspa_runtime*r,const mspa_observe_input*i,mspa_observe_result*out){try{if(!r||!i||!out)return MSPA_INVALID_ARGUMENT;ObserveInput x{};x.agent=aid(i->agent);x.proposition.predicate=PredicateId(i->predicate_id);x.proposition.name_space=NamespaceId(i->namespace_id);x.proposition.positive=i->positive!=0;x.time.process_time=PsychTime(i->process_time);x.time.has_event_time=i->has_event_time!=0;x.time.event_time=PsychTime(i->event_time);x.perceived_certainty=i->perceived_certainty;x.source_trust=i->source_trust;if(i->argument_count&& !i->arguments)return MSPA_INVALID_ARGUMENT;for(size_t n=0;n<i->argument_count;++n){PropositionArg a{};a.role=i->arguments[n].role?i->arguments[n].role:"";a.value=i->arguments[n].value?i->arguments[n].value:"";a.has_agent=i->arguments[n].has_agent!=0;if(a.has_agent)a.agent=aid(i->arguments[n].agent);a.has_concept=i->arguments[n].has_concept!=0;if(a.has_concept)a.concept_id=ConceptId(i->arguments[n].concept_id);x.proposition.arguments.push_back(std::move(a));}auto q=r->impl->observe(x);auto s=take(q);if(s!=MSPA_OK)return s;out->state_changed=q.value_if()->state_changed;out->decision_recommended=q.value_if()->decision_recommended;out->current_action_threatened=q.value_if()->current_action_threatened;out->urgency=static_cast<uint32_t>(q.value_if()->urgency);out->diagnostic_token=q.value_if()->diagnostic_token;return MSPA_OK;}catch(const std::bad_alloc&){err="out of memory";return MSPA_OUT_OF_MEMORY;}catch(...){err="unexpected observe C ABI exception";return MSPA_INTERNAL_ERROR;}}
mspa_status mspa_decide(mspa_runtime*r,mspa_agent_id a,const mspa_action_option*opts,size_t count,uint64_t t,uint64_t current,mspa_decision_result*out){try{if(!r||!out||(count&&!opts))return MSPA_INVALID_ARGUMENT;std::vector<ActionOption>v;v.reserve(count);for(size_t n=0;n<count;++n)v.push_back(convert_option(opts[n],aid(a)));auto q=r->impl->decide(aid(a),v,PsychTime(t),ActionContinuityKey(current));return fill_decision(q,out);}catch(const std::bad_alloc&){err="out of memory";return MSPA_OUT_OF_MEMORY;}catch(...){err="unexpected decide C ABI exception";return MSPA_INTERNAL_ERROR;}}
mspa_status mspa_decide_ex(mspa_runtime*r,mspa_agent_id a,const mspa_action_option*opts,size_t count,const mspa_need_signal*needs,size_t need_count,const mspa_named_signal*signals,size_t signal_count,float urgency,uint64_t t,uint64_t current,mspa_decision_result*out){try{if(!r||!out||(count&&!opts)||(need_count&&!needs)||(signal_count&&!signals))return MSPA_INVALID_ARGUMENT;std::vector<ActionOption>v;v.reserve(count);for(size_t n=0;n<count;++n)v.push_back(convert_option(opts[n],aid(a)));DecisionContext c{};for(size_t n=0;n<need_count;++n)c.needs.push_back({ConceptId(needs[n].concept_id),needs[n].pressure});for(size_t n=0;n<signal_count;++n)if(signals[n].name)c.signals[signals[n].name]=signals[n].value;c.urgency=urgency;auto q=r->impl->decide(aid(a),v,c,PsychTime(t),ActionContinuityKey(current));return fill_decision(q,out);}catch(const std::bad_alloc&){err="out of memory";return MSPA_OUT_OF_MEMORY;}catch(...){err="unexpected decide_ex C ABI exception";return MSPA_INTERNAL_ERROR;}}
mspa_status mspa_report(mspa_runtime*r,mspa_agent_id a,uint64_t action,int success,uint64_t t){return mspa_report_ex(r,a,action,success,nullptr,0,nullptr,0,t);}mspa_status mspa_report_ex(mspa_runtime*r,mspa_agent_id a,uint64_t action,int success,const char* const*ctx,size_t ctxn,const char* const*outcomes,size_t outn,uint64_t t){try{if(!r||(ctxn&&!ctx)||(outn&&!outcomes))return MSPA_INVALID_ARGUMENT;ReportInput x{};x.agent=aid(a);x.action_type=ActionTypeId(action);x.success=success!=0;x.process_time=PsychTime(t);for(size_t i=0;i<ctxn;++i)if(ctx[i])x.context_tags.emplace_back(ctx[i]);for(size_t i=0;i<outn;++i)if(outcomes[i])x.outcome_tags.emplace_back(outcomes[i]);auto q=r->impl->report(x);return take(q);}catch(const std::bad_alloc&){err="out of memory";return MSPA_OUT_OF_MEMORY;}catch(...){err="unexpected report_ex C ABI exception";return MSPA_INTERNAL_ERROR;}}mspa_status mspa_advance(mspa_runtime*r,mspa_agent_id a,uint64_t t){if(!r)return MSPA_INVALID_ARGUMENT;auto q=r->impl->advance_to(aid(a),PsychTime(t));return take(q);}
mspa_status mspa_agent_export(mspa_runtime*r,mspa_agent_id a,uint64_t t,mspa_buffer*out){try{if(!r||!out)return MSPA_INVALID_ARGUMENT;auto q=r->impl->export_agent_bytes(aid(a),PsychTime(t));auto s=take(q);if(s!=MSPA_OK)return s;out->size=q.value_if()->size();out->data=static_cast<uint8_t*>(std::malloc(out->size));if(out->size&&!out->data){err="out of memory";out->size=0;return MSPA_OUT_OF_MEMORY;}if(out->size)std::memcpy(out->data,q.value_if()->data(),out->size);return MSPA_OK;}catch(...){err="unexpected export C ABI exception";return MSPA_INTERNAL_ERROR;}}
mspa_status mspa_agent_import(mspa_runtime*r,const uint8_t*data,size_t size,mspa_agent_id destination,uint64_t t){try{if(!r||(size&&!data))return MSPA_INVALID_ARGUMENT;std::vector<uint8_t>b; if(size)b.assign(data,data+size);ImportOptions o{};o.destination_id=aid(destination);o.import_time=PsychTime(t);o.destination_seed_root=r->impl->config().seed_root;auto q=r->impl->import_agent_bytes(b,o);return take(q);}catch(const std::bad_alloc&){err="out of memory";return MSPA_OUT_OF_MEMORY;}catch(...){err="unexpected import C ABI exception";return MSPA_INTERNAL_ERROR;}}
void mspa_buffer_free(mspa_buffer*b){if(!b)return;std::free(b->data);b->data=nullptr;b->size=0;}const char*mspa_last_error(void){return err.c_str();}
}
